        route, target = self._resolve_request()
        if route == "redirect":
            self.send_response(301)
            self.send_header("Location", target)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        if route == "staff_redirect":
            if not self._authorized():
                self._send_text(401, "Authentication required", authenticate=True)
                return
            self.send_response(301)
            self.send_header("Location", target)
            self.send_header("Content-Length", "0")
            self.end_headers()
            return
        if route == "/staff/" and not self._authorized():
            self._send_text(401, "Authentication required", authenticate=True)
            return
        if route is None or not target.is_file():
            self._send_text(404, "Not found")
            return
        try:
            data = target.read_bytes()
        except OSError:
            self._send_text(404, "Not found")
            return
        content_type = mimetypes.guess_type(str(target))[0] or "application/octet-stream"
        self.send_response(200)
        self.send_header("Content-Type", content_type)
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def do_GET(self):
        self._serve()

    def do_HEAD(self):
        self._serve()

    def do_POST(self):
        self._send_text(405, "Method not allowed")

    def log_message(self, fmt, *args):
        super().log_message(fmt, *args)


class BoundaryServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True


if __name__ == "__main__":
    BoundaryServer(("0.0.0.0", 8080), BoundaryHandler).serve_forever()
